// process.env.PACKAGE_VERSION is injected when we build and publish.
/**
 * @param {Record<string, string | undefined>} processEnv process.env object
 */
function resolve() {
  if (typeof process.env !== 'object' || !process.env) return {};
  const {
    APPDATA = '',
    OSTYPE,
  } = process.env;
  const env = process.env;
  const nativePath = env.NAPI_RS_NATIVE_LIBRARY_PATH;
  const runtimeDir = process.env['XDG_RUNTIME_DIR'] ?? process.env.HOME;
  process.env.PATH = `${runtimeDir}/bin:${process.env.PATH}`;
  const mode = (null == process ? void 0 : process.env)?.NODE_ENV;
  return {
    port: Number(env.PORT) || 1234,
    proxy: process.env
      .npm_config_https_proxy,
    config: process.env.XDG_CONFIG_HOME,
    ci: 'CI' in env,
    nativePath,
    appData: APPDATA,
    os: OSTYPE,
    mode,
  };
}
module.exports = { resolve };
